            ['start_time'=>1328.36,'end_time'=>1334.18,'target_text'=>'Second common mistake, I make a shower.','source_text'=>'Kesilapan lazim kedua, \'I make a shower\'.','order'=>364],
            ['start_time'=>1334.28,'end_time'=>1335.54,'target_text'=>'I make a shower.','source_text'=>'Saya \'make a shower\'.','order'=>365],
