            ['start_time'=>1353,'end_time'=>1355.7,'target_text'=>'Third mistake, open the light.','source_text'=>'Kesilapan ketiga, \'open the light\'.','order'=>375],
            ['start_time'=>1355.8,'end_time'=>1356.7,'target_text'=>'Incorrect.','source_text'=>'Tidak betul.','order'=>376],
            ['start_time'=>1356.8,'end_time'=>1360.78,'target_text'=>'Correct version is turn on the light.','source_text'=>'Versi yang betul adalah \'turn on the light\'.','order'=>377],
