            ['start_time'=>798.32,'end_time'=>798.72,'target_text'=>'>> No.','source_text'=>'>> Ia adalah minuman berasaskan teh herba.','order'=>339],
            ['start_time'=>798.8,'end_time'=>801.32,'target_text'=>'>> It\'s a like a tea.','source_text'=>'>> Oh.','order'=>340],
            ['start_time'=>801.92,'end_time'=>803.5,'target_text'=>'>> Oh.','source_text'=>'>> Mak cuba rasa.','order'=>341],
            ['start_time'=>803.6,'end_time'=>805.1,'target_text'=>'>> Try it.','source_text'=>'Macam teh herba putih.','order'=>342],
            ['start_time'=>805.2,'end_time'=>805.82,'target_text'=>'Like a white.','source_text'=>'>> Sedap gila, kawan.','order'=>343],
            ['start_time'=>805.92,'end_time'=>806.38,'target_text'=>'>> So good, dude.','source_text'=>'Saya memang sukakannya.','order'=>344],
            ['start_time'=>806.48,'end_time'=>806.88,'target_text'=>'I love it.','source_text'=>'Rasanya macam teh manis yang menyegarkan.','order'=>345],
            ['start_time'=>806.96,'end_time'=>808.46,'target_text'=>'It\'s like a sweet tea.','source_text'=>'>> Minuman botani herba yang tertera di label tin, sedap sangat.','order'=>346],
