        foreach ([
            ['start_time'=>0,'end_time'=>1.42,'target_text'=>'Welcome back to new video, guys.','source_text'=>'Selamat kembali ke video baru, kawan-kawan.','order'=>1],
            ['start_time'=>1.52,'end_time'=>5.22,'target_text'=>'Today, we are in Ho Chi Minh City, Vietnam.','source_text'=>'Hari ini, kita berada di Bandar Ho Chi Minh, Vietnam.','order'=>2],
            ['start_time'=>5.32,'end_time'=>10.46,'target_text'=>'Today, we have a clear and natural comprehensible input vlog.','source_text'=>'Hari ini, kita ada vlog input mudah difahami yang jelas dan santai.','order'=>3],
            ['start_time'=>10.56,'end_time'=>17.9,'target_text'=>'In this video, we\'ll be walking around the city, visiting different places, and describing everything using comprehensible','source_text'=>'Dalam video ni, kita akan berjalan-jalan keliling bandar, melawat pelbagai tempat, dan menceritakan segalanya menggunakan kaedah input','order'=>4],
