        foreach ([
            ['start_time'=>0,'end_time'=>6.34,'target_text'=>'The faster you can start thinking in English, the faster you can start speaking English naturally.','source_text'=>'Semakin pantas anda mula berfikir dalam bahasa Inggeris, semakin pantas anda boleh bertutur bahasa Inggeris secara semula jadi.','order'=>1],
